"""Controlled coding-agent handoff.

Writes agent instruction files and the prompt into a directory the user chose,
after an explicit preview and confirmation. Guarantees:
* file paths are generated by Prompt Studio (never taken from the request),
* existing files are never overwritten unless listed in `overwrite`, and a
  timestamped backup is written first,
* symlinked targets or parents are refused; every target must resolve inside
  the chosen directory,
* writes are atomic (temp file + rename),
* nothing is executed: the suggested command is only displayed.
"""

from __future__ import annotations

import os
import shlex
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from pydantic import BaseModel

from ..engine.export.renderers import render
from ..engine.spec import ProjectSpec
from ..engine.templates.profiles import get_profile
from ..errors import AppError, bad_request
from .codebase_service import validate_root

WRITE_CONFIRM = "WRITE"
PROMPT_DIR = ".prompt-studio"


class HandoffFile(BaseModel):
    path: str
    purpose: str
    exists: bool
    existing_size: int | None
    content: str


class HandoffPlan(BaseModel):
    root: str
    profile_id: str
    files: list[HandoffFile]
    command: str
    command_note: str


def _instruction_file(profile_id: str, spec: ProjectSpec) -> tuple[str, str, str]:
    """(relative path, purpose, content) of the agent's persistent instruction file."""
    if profile_id == "claude_code":
        return "CLAUDE.md", "Claude Code project instructions", render("claude_md", spec, None).content
    if profile_id == "cursor":
        f = render("cursor_mdc", spec, None)
        return f".cursor/rules/{f.filename}", "Cursor project rule", f.content
    return "AGENTS.md", "Agent instructions (AGENTS.md convention)", render("agents_md", spec, None).content


def _command(profile_id: str, root: Path) -> tuple[str, str]:
    cd = f"cd {shlex.quote(str(root))}"
    prompt = f'"$(cat {PROMPT_DIR}/PROMPT.md)"'
    if profile_id == "claude_code":
        return (
            f"{cd} && claude {prompt}",
            "Starts an interactive Claude Code session with the prompt. Review before running.",
        )
    if profile_id == "codex":
        return (
            f"{cd} && codex {prompt}",
            "Starts an interactive Codex CLI session with the prompt. Review before running.",
        )
    if profile_id == "cursor":
        return cd, "Open this folder in Cursor and paste .prompt-studio/PROMPT.md into the Agent chat."
    return cd, "Open the folder with your agent and give it the contents of .prompt-studio/PROMPT.md."


def plan(path: str, profile_id: str, spec: ProjectSpec, prompt: str) -> HandoffPlan:
    root = validate_root(path)
    profile = get_profile(profile_id)
    if not profile.coding:
        raise bad_request("Handoff is only available for coding-agent profiles.", "unsupported_profile")
    rel, purpose, content = _instruction_file(profile.id, spec)
    specs = [
        (rel, purpose, content),
        (f"{PROMPT_DIR}/PROMPT.md", "Task prompt for the agent", prompt),
        (f"{PROMPT_DIR}/TASKS.md", "Task checklist from confirmed requirements", render("tasks", spec, None).content),
    ]
    files = []
    for rel_path, why, body in specs:
        target = root / rel_path
        exists = target.exists() or target.is_symlink()
        size = target.stat().st_size if exists and target.is_file() and not target.is_symlink() else None
        files.append(HandoffFile(path=rel_path, purpose=why, exists=exists, existing_size=size, content=body))
    command, note = _command(profile.id, root)
    return HandoffPlan(root=str(root), profile_id=profile.id, files=files, command=command, command_note=note)


def _safe_target(root: Path, rel_path: str) -> Path:
    target = root / rel_path
    # Refuse any symlink along the way (target or a parent directory inside root).
    p = target
    while p != root:
        if p.is_symlink():
            raise AppError(400, "symlink_refused", f"Refusing to write through a symlink: {rel_path}")
        p = p.parent
    if not target.parent.resolve().is_relative_to(root):
        raise AppError(400, "path_not_allowed", f"Target escapes the chosen directory: {rel_path}")
    return target


def write(
    path: str, profile_id: str, spec: ProjectSpec, prompt: str, overwrite: list[str], confirm: str
) -> dict[str, Any]:
    if confirm != WRITE_CONFIRM:
        raise bad_request(f"Type {WRITE_CONFIRM} to authorize writing files.", "confirmation_required")
    p = plan(path, profile_id, spec, prompt)
    root = Path(p.root)
    stamp = datetime.now(UTC).strftime("%Y%m%d-%H%M%S")
    written, skipped, backups = [], [], []
    for f in p.files:
        target = _safe_target(root, f.path)
        if f.exists and f.path not in overwrite:
            skipped.append(f.path)
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        _safe_target(root, f.path)  # re-check after creating directories
        if f.exists:
            if not target.is_file():
                raise AppError(400, "not_a_file", f"Cannot overwrite non-file: {f.path}")
            backup = target.with_name(f"{target.name}.prompt-studio-bak-{stamp}")
            backup.write_bytes(target.read_bytes())
            backups.append(str(backup.relative_to(root)))
        tmp = target.with_name(f".{target.name}.prompt-studio-tmp")
        tmp.write_text(f.content, encoding="utf-8")
        os.replace(tmp, target)
        written.append(f.path)
    return {
        "root": p.root,
        "written": written,
        "skipped_existing": skipped,
        "backups": backups,
        "command": p.command,
        "command_note": p.command_note,
    }
